"use client";

import { useEffect, useState, useCallback } from "react";
import { Users, Search, Phone, Mail, MapPin, User, GraduationCap } from "lucide-react";
import { receptionistApi } from "@/lib/receptionistApi";
import { useAuth } from "@/lib/auth-context";

export default function ReceptionistParentsPage() {
  const { user } = useAuth();
  const [parents, setParents] = useState<any[]>([]);
  const [classes, setClasses] = useState<any[]>([]);
  const [search, setSearch] = useState("");
  const [selectedClassId, setSelectedClassId] = useState("");

  const [page, setPage] = useState(1);
  const [pages, setPages] = useState(1);
  const [total, setTotal] = useState(0);

  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");

  useEffect(() => {
    receptionistApi
      .getClasses()
      .then((res) => setClasses(res?.data || []))
      .catch(() => setClasses([]));
  }, []);

  const loadParents = useCallback(async () => {
    setLoading(true);
    setError("");
    try {
      const res = await receptionistApi.getParents({
        search,
        classId: selectedClassId || undefined,
        page,
        limit: 25,
      });
      setParents(res?.data?.parents || []);
      setTotal(res?.data?.total || 0);
      setPages(res?.data?.pages || 1);
    } catch (err: any) {
      setError(err?.message || "Unable to load parent/guardian records.");
      setParents([]);
    } finally {
      setLoading(false);
    }
  }, [search, selectedClassId, page]);

  useEffect(() => {
    void loadParents();
  }, [loadParents]);

  return (
    <div className="space-y-6 pb-12">
      {/* Header */}
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 border-b border-zinc-200 pb-4">
        <div>
          <h1 className="text-2xl font-black text-zinc-950 flex items-center gap-2">
            <Users className="h-6 w-6 text-school-primary" />
            Parents & Guardians Directory
          </h1>
          <p className="text-xs text-zinc-500">
            Front-desk directory of parents and legal guardians linked to active enrolled students.
          </p>
        </div>
      </div>

      {error && (
        <p role="alert" className="rounded-xl border border-red-200 bg-red-50 p-4 text-xs font-semibold text-red-800">
          {error}
        </p>
      )}

      {/* Filter Controls */}
      <div className="bg-white border border-zinc-200 p-4 rounded-2xl shadow-xs grid grid-cols-1 sm:grid-cols-2 gap-4 text-xs">
        <div>
          <label className="block font-bold text-zinc-700 uppercase mb-1">Search Parent / Student</label>
          <div className="relative">
            <input
              type="text"
              placeholder="Parent name, contact phone, student name, roll no…"
              value={search}
              onChange={(e) => {
                setSearch(e.target.value);
                setPage(1);
              }}
              className="w-full pl-8 pr-3 py-2 bg-zinc-50 border border-zinc-200 rounded-lg focus:outline-none"
            />
            <Search className="w-3.5 h-3.5 text-zinc-400 absolute left-2.5 top-3" />
          </div>
        </div>

        <div>
          <label className="block font-bold text-zinc-700 uppercase mb-1">Filter by Student's Class</label>
          <select
            value={selectedClassId}
            onChange={(e) => {
              setSelectedClassId(e.target.value);
              setPage(1);
            }}
            className="w-full px-3 py-2 bg-zinc-50 border border-zinc-200 rounded-lg font-semibold focus:outline-none"
          >
            <option value="">All Classes</option>
            {classes.map((cls) => (
              <option key={cls._id} value={cls._id}>
                {cls.name}
              </option>
            ))}
          </select>
        </div>
      </div>

      {/* Parents Table */}
      <div className="bg-white border border-zinc-200 rounded-2xl shadow-xs overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-left text-xs min-w-[850px]">
            <thead className="bg-zinc-50 border-b border-zinc-200 text-zinc-500 font-bold uppercase tracking-wider text-[11px]">
              <tr>
                <th className="py-3 px-4">Parent / Guardian</th>
                <th className="py-3 px-4">Primary Contact</th>
                <th className="py-3 px-4">Linked Student</th>
                <th className="py-3 px-4">Class & Section</th>
                <th className="py-3 px-4">Residential Address</th>
                <th className="py-3 px-4">Emergency Contact</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-zinc-100">
              {loading ? (
                <tr>
                  <td colSpan={6} className="py-12 text-center text-zinc-500">
                    Loading parent directory…
                  </td>
                </tr>
              ) : parents.length === 0 ? (
                <tr>
                  <td colSpan={6} className="py-12 text-center text-zinc-500">
                    No matching parent records found.
                  </td>
                </tr>
              ) : (
                parents.map((parent, idx) => (
                  <tr key={`${parent._id}-${idx}`} className="hover:bg-zinc-50/80 transition-colors">
                    <td className="py-3.5 px-4 font-bold text-zinc-950">
                      <div className="flex items-center gap-2">
                        <div className="w-7 h-7 rounded-lg bg-blue-50 text-blue-700 font-bold flex items-center justify-center shrink-0">
                          {parent.guardianName.charAt(0).toUpperCase()}
                        </div>
                        <div>
                          <p>{parent.guardianName}</p>
                          <span className="text-[10px] text-zinc-400 font-normal">
                            Relation: {parent.guardianRelation}
                          </span>
                        </div>
                      </div>
                    </td>

                    <td className="py-3.5 px-4 font-mono font-semibold text-zinc-900">
                      <div className="flex items-center gap-1.5">
                        <Phone className="w-3 h-3 text-zinc-400 shrink-0" />
                        <span>{parent.guardianPhone}</span>
                      </div>
                      {parent.guardianEmail && (
                        <span className="text-[10px] text-zinc-400 font-mono block">
                          {parent.guardianEmail}
                        </span>
                      )}
                    </td>

                    <td className="py-3.5 px-4 font-bold text-zinc-900">
                      <div className="flex items-center gap-1.5">
                        <GraduationCap className="w-3.5 h-3.5 text-school-primary shrink-0" />
                        <span>{parent.studentName}</span>
                      </div>
                      <span className="text-[10px] text-zinc-400 font-mono block">
                        Roll: #{parent.rollNumber || "—"}
                      </span>
                    </td>

                    <td className="py-3.5 px-4 text-zinc-700 font-medium">
                      {parent.className}{" "}
                      {parent.sectionName ? `(${parent.sectionName})` : ""}
                    </td>

                    <td className="py-3.5 px-4 text-zinc-600 max-w-xs truncate">
                      {parent.address}
                    </td>

                    <td className="py-3.5 px-4 text-zinc-700">
                      {parent.emergencyContact?.name ? (
                        <div>
                          <p className="font-semibold text-zinc-900">
                            {parent.emergencyContact.name}
                          </p>
                          <p className="text-[10px] font-mono text-zinc-500">
                            {parent.emergencyContact.phone}
                          </p>
                        </div>
                      ) : (
                        <span className="text-zinc-400">—</span>
                      )}
                    </td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>

        {/* Pagination */}
        <div className="p-4 border-t border-zinc-200 flex flex-col sm:flex-row items-center justify-between gap-3 text-xs text-zinc-500">
          <span>
            Showing {parents.length} of {total} parent contacts
          </span>
          <div className="flex items-center gap-2">
            <button
              onClick={() => setPage((p) => Math.max(1, p - 1))}
              disabled={page <= 1 || loading}
              className="px-3 py-1.5 border border-zinc-200 rounded-lg hover:bg-zinc-50 disabled:opacity-50 font-semibold"
            >
              Previous
            </button>
            <span className="font-bold text-zinc-800">
              Page {page} of {Math.max(1, pages)}
            </span>
            <button
              onClick={() => setPage((p) => Math.min(pages, p + 1))}
              disabled={page >= pages || loading}
              className="px-3 py-1.5 border border-zinc-200 rounded-lg hover:bg-zinc-50 disabled:opacity-50 font-semibold"
            >
              Next
            </button>
          </div>
        </div>
      </div>
    </div>
  );
}

"use client";

import { useEffect, useState } from "react";
import { Award, Printer, AlertCircle, Building2 } from "lucide-react";
import { schoolAdminApi } from "@/lib/schoolAdminApi";
import { useAuth } from "@/lib/auth-context";

interface StudentRecord {
  _id: string;
  name: string;
  admissionNumber: string;
  rollNumber: string;
  className: string;
  sectionName?: string;
  parentInfo?: {
    fatherName?: string;
  };
  dob?: string;
  admissionDate?: string;
}

export default function CertificatesGeneratorPage() {
  const { user } = useAuth();
  const [certType, setCertType] = useState<"BONAFIDE" | "CHARACTER" | "LEAVING" | "TRANSFER" | "RESULT">("BONAFIDE");
  const [students, setStudents] = useState<StudentRecord[]>([]);
  const [selectedStudentId, setSelectedStudentId] = useState<string>("");
  const [schoolProfile, setSchoolProfile] = useState<any>(null);
  const [reason, setReason] = useState("Official Verification & Record Keeping");
  const [issueDate, setIssueDate] = useState(() => new Date().toISOString().split("T")[0]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");

  useEffect(() => {
    async function loadData() {
      try {
        const [profileRes, studentRes] = await Promise.all([
          schoolAdminApi.getSchoolProfile().catch(() => null),
          schoolAdminApi.getStudents(),
        ]);

        if (profileRes?.data) setSchoolProfile(profileRes.data);

        const list = studentRes?.data?.students || studentRes?.data || (Array.isArray(studentRes) ? studentRes : []);
        setStudents(list);

        if (list.length > 0) {
          setSelectedStudentId(list[0]._id);
        }
      } catch (err: any) {
        setError(err?.message || "Failed to load student records for certificate generation.");
      } finally {
        setLoading(false);
      }
    }
    loadData();
  }, []);

  const student = students.find((s) => s._id === selectedStudentId);
  const schoolName = schoolProfile?.name || user?.school?.name || "School ERP System";
  const logoUrl = schoolProfile?.logoUrl || (user?.school as any)?.logoUrl || "";
  const schoolAddress = schoolProfile?.address || (user?.school as any)?.address || "";
  const schoolPhone = schoolProfile?.phone || (user?.school as any)?.phone || "";

  const certNumber = student
    ? `CERT-${certType.slice(0, 3)}-${(student.admissionNumber || student.rollNumber || student._id.slice(-4)).split("-").pop()}`
    : "";

  const handlePrint = () => {
    window.print();
  };

  if (loading) {
    return (
      <div className="p-12 text-center text-sm font-semibold text-zinc-500 animate-pulse bg-white border border-zinc-200 rounded-xl">
        Loading real student records & institutional branding...
      </div>
    );
  }

  if (students.length === 0) {
    return (
      <div className="bg-white border border-zinc-200 rounded-xl p-12 text-center space-y-3">
        <AlertCircle className="w-10 h-10 text-zinc-300 mx-auto" />
        <h3 className="text-base font-bold text-zinc-900">No Enrolled Students Found</h3>
        <p className="text-xs text-zinc-500 max-w-sm mx-auto">
          No active student records exist in the database for certificate generation.
        </p>
      </div>
    );
  }

  return (
    <div className="space-y-6 pb-12">
      {/* Controls Header */}
      <div className="print:hidden bg-white border border-zinc-200 p-4 rounded-xl shadow-xs flex flex-col sm:flex-row justify-between items-center gap-4">
        <div>
          <h1 className="text-xl font-black text-zinc-950 flex items-center gap-2">
            <Award className="h-5 w-5 text-red-600" />
            Institutional Certificate Generator
          </h1>
          <p className="text-xs text-zinc-500">Issue Bonafide, Character, School Leaving, Transfer & Result certificates from real student records</p>
        </div>

        <div className="flex flex-wrap items-center gap-2 w-full sm:w-auto">
          <select
            value={certType}
            onChange={(e: any) => setCertType(e.target.value)}
            className="text-xs font-bold border border-zinc-300 rounded-lg p-2.5 bg-zinc-50 focus:outline-none"
          >
            <option value="BONAFIDE">Bonafide Student Certificate</option>
            <option value="CHARACTER">Character Certificate</option>
            <option value="LEAVING">School Leaving Certificate (SLC)</option>
            <option value="TRANSFER">School Transfer Certificate</option>
            <option value="RESULT">Academic Result Certificate</option>
          </select>

          <select
            value={selectedStudentId}
            onChange={(e) => setSelectedStudentId(e.target.value)}
            className="text-xs font-bold border border-zinc-300 rounded-lg p-2.5 bg-zinc-50 focus:outline-none"
          >
            {students.map((s) => (
              <option key={s._id} value={s._id}>
                {s.name} ({s.className} - Roll {s.rollNumber || "—"})
              </option>
            ))}
          </select>

          <button
            onClick={handlePrint}
            disabled={!student}
            className="flex items-center gap-2 px-4 py-2.5 text-xs font-bold bg-zinc-950 hover:bg-zinc-800 text-white rounded-lg transition-colors shadow-xs shrink-0 disabled:opacity-50"
          >
            <Printer className="h-4 w-4" />
            Print Official Certificate
          </button>
        </div>
      </div>

      {error && (
        <div className="bg-red-50 border border-red-200 text-red-800 px-4 py-3 rounded-xl text-xs font-medium flex items-center gap-2">
          <AlertCircle className="h-4 w-4 text-red-600 shrink-0" />
          <span>{error}</span>
        </div>
      )}

      {/* Certificate Document Card (Print Friendly) */}
      {student && (
        <div className="bg-white border-4 border-double border-zinc-900 p-10 rounded-none shadow-md max-w-3xl mx-auto space-y-8 text-zinc-950 print:border-0 print:p-0 print:shadow-none font-serif">
          {/* Header */}
          <div className="text-center space-y-2 border-b-2 border-zinc-900 pb-6">
            <div className="flex items-center justify-center gap-3">
              {logoUrl ? (
                <img src={logoUrl} alt={schoolName} className="h-12 w-12 object-contain" />
              ) : (
                <div className="w-12 h-12 bg-red-600 text-white font-sans font-black flex items-center justify-center text-2xl rounded">
                  {schoolName.charAt(0)}
                </div>
              )}
              <div>
                <h2 className="text-2xl font-black tracking-tight text-zinc-950 uppercase font-sans">{schoolName}</h2>
                <p className="text-xs font-bold text-zinc-600 uppercase tracking-widest font-sans">Affiliated & Recognized Educational Institution</p>
              </div>
            </div>
            {schoolAddress && <p className="text-[11px] text-zinc-500 font-mono">{schoolAddress} {schoolPhone ? `| Phone: ${schoolPhone}` : ""}</p>}
          </div>

          {/* Certificate Title */}
          <div className="text-center py-2">
            <span className="border-b-2 border-t-2 border-zinc-900 py-1.5 px-8 text-base font-black uppercase tracking-widest font-sans inline-block">
              {certType === "BONAFIDE" && "BONAFIDE STUDENT CERTIFICATE"}
              {certType === "CHARACTER" && "CHARACTER & CONDUCT CERTIFICATE"}
              {certType === "LEAVING" && "SCHOOL LEAVING CERTIFICATE"}
              {certType === "TRANSFER" && "TRANSFER CERTIFICATE"}
              {certType === "RESULT" && "ACADEMIC RESULT CERTIFICATE"}
            </span>
          </div>

          {/* Certificate Serial Metadata */}
          <div className="flex justify-between items-center text-xs font-mono text-zinc-600">
            <span>Certificate No: <strong className="text-zinc-950">{certNumber}</strong></span>
            <span>Date of Issue: <strong className="text-zinc-950">{issueDate}</strong></span>
          </div>

          {/* Certificate Legal Wording Body */}
          <div className="text-sm leading-relaxed text-justify space-y-4 text-zinc-900 pt-2">
            {certType === "BONAFIDE" && (
              <p>
                This is to certify that <strong>{student.name}</strong>, Son/Daughter of <strong>{student.parentInfo?.fatherName || "N/A"}</strong>, bearing Roll Number <strong>{student.rollNumber || "N/A"}</strong> and Admission ID <strong>{student.admissionNumber || "N/A"}</strong>, is a bonafide student of this institution currently studying in <strong>{student.className} {student.sectionName || ""}</strong>.
              </p>
            )}

            {certType === "CHARACTER" && (
              <p>
                This is to certify that <strong>{student.name}</strong>, Son/Daughter of <strong>{student.parentInfo?.fatherName || "N/A"}</strong>, bearing Roll Number <strong>{student.rollNumber || "N/A"}</strong>, has been a regular student of <strong>{student.className}</strong> in this institution. During his/her stay at this school, his/her general conduct and moral character have been found to be <strong>Exemplary and Outstanding</strong>. To the best of my knowledge, he/she bears a good reputation.
              </p>
            )}

            {certType === "LEAVING" && (
              <p>
                This is to certify that <strong>{student.name}</strong>, Son/Daughter of <strong>{student.parentInfo?.fatherName || "N/A"}</strong>, was admitted to this school and left the institution on <strong>{issueDate}</strong> after completing studies in <strong>{student.className}</strong>. All school dues have been cleared.
              </p>
            )}

            {certType === "TRANSFER" && (
              <p>
                This Transfer Certificate is issued to <strong>{student.name}</strong>, Son/Daughter of <strong>{student.parentInfo?.fatherName || "N/A"}</strong>, studying in <strong>{student.className}</strong>, enabling transfer to another recognized institution. All institutional fees have been cleared.
              </p>
            )}

            {certType === "RESULT" && (
              <p>
                This is to certify that <strong>{student.name}</strong>, Roll Number <strong>{student.rollNumber || "N/A"}</strong>, appeared in the Academic Examination for <strong>{student.className}</strong> and passed the examination with distinction.
              </p>
            )}

            <p className="italic text-xs text-zinc-600">
              This certificate is issued upon official request for <strong>{reason}</strong>.
            </p>
          </div>

          {/* Signatures & Seal */}
          <div className="pt-12 grid grid-cols-2 gap-12 items-end text-center text-xs font-sans">
            <div className="flex flex-col items-center">
              <div className="w-20 h-20 border-2 border-dashed border-red-500 rounded-full flex flex-col items-center justify-center text-[9px] font-bold text-red-600 uppercase tracking-tighter mb-2 p-1 text-center">
                Official Seal
              </div>
              <span className="text-[10px] font-mono text-zinc-500">Checked By: Exam Office</span>
            </div>

            <div className="border-t border-zinc-900 pt-2 font-bold text-zinc-950">
              Principal Stamp & Authorized Signature
            </div>
          </div>

          {/* Digital Footer */}
          <div className="border-t border-zinc-200 pt-3 flex justify-between items-center text-[10px] font-mono text-zinc-400 font-sans">
            <span>Generated by {schoolName} ERP</span>
            <span>Verification Code: {certNumber}</span>
          </div>
        </div>
      )}
    </div>
  );
}

"use client";

import { useEffect, useState } from "react";
import { Printer, GraduationCap, AlertCircle, Building2 } from "lucide-react";
import { schoolAdminApi } from "@/lib/schoolAdminApi";
import { useAuth } from "@/lib/auth-context";
import { useSearchParams } from "next/navigation";

interface ProcessedResultItem {
  _id: string;
  examId: string;
  examTitle: string;
  classId: string;
  className: string;
  studentId: string;
  studentName: string;
  rollNumber: string;
  admissionNumber?: string;
  subjectScores: Array<{
    subjectId?: string;
    subjectName: string;
    maxMarks: number;
    obtainedMarks: number;
    grade: string;
    remarks?: string;
  }>;
  totalMaxMarks: number;
  totalObtainedMarks: number;
  percentage: number;
  overallGrade: string;
  rank?: number;
  status: "PASSED" | "PROMOTED" | "FAILED";
}

export default function MarksheetsPage() {
  const { user } = useAuth();
  const searchParams = useSearchParams();

  const [exams, setExams] = useState<any[]>([]);
  const [classes, setClasses] = useState<any[]>([]);
  const [schoolProfile, setSchoolProfile] = useState<any>(null);

  const [selectedExam, setSelectedExam] = useState<string>(searchParams.get("examId") || "");
  const [selectedClass, setSelectedClass] = useState<string>(searchParams.get("classId") || "");

  const [results, setResults] = useState<ProcessedResultItem[]>([]);
  const [selectedStudentId, setSelectedStudentId] = useState<string>(searchParams.get("studentId") || "");
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");

  // 1. Load School Profile, Exams & Classes
  useEffect(() => {
    async function loadOptions() {
      try {
        const [profileRes, examRes, classRes] = await Promise.all([
          schoolAdminApi.getSchoolProfile().catch(() => null),
          schoolAdminApi.getExamSchedules(),
          schoolAdminApi.getClasses(),
        ]);

        if (profileRes?.data) {
          setSchoolProfile(profileRes.data);
        }

        const examList = examRes?.data || [];
        const classList = classRes?.data || [];

        setExams(examList);
        setClasses(classList);

        if (!selectedExam && examList.length > 0) {
          setSelectedExam(examList[0]._id);
        }
        if (!selectedClass && classList.length > 0) {
          setSelectedClass(classList[0]._id);
        }
      } catch (err: any) {
        setError(err?.message || "Failed to load options.");
      }
    }
    loadOptions();
  }, []);

  // 2. Fetch Results for Selected Exam & Class
  useEffect(() => {
    if (!selectedExam || !selectedClass) {
      setResults([]);
      setLoading(false);
      return;
    }

    setLoading(true);
    setError("");

    schoolAdminApi
      .getResults(selectedExam, selectedClass)
      .then((res: any) => {
        const list = res?.data || (Array.isArray(res) ? res : []);
        setResults(list);
        if (list.length > 0) {
          const queryStudentId = searchParams.get("studentId");
          if (queryStudentId && list.some((r: any) => String(r.studentId) === queryStudentId)) {
            setSelectedStudentId(queryStudentId);
          } else {
            setSelectedStudentId(String(list[0].studentId));
          }
        } else {
          setSelectedStudentId("");
        }
      })
      .catch((err: any) => {
        setError(err?.message || "Failed to load examination results for marksheets.");
        setResults([]);
      })
      .finally(() => setLoading(false));
  }, [selectedExam, selectedClass]);

  const currentResult = results.find((r) => String(r.studentId) === selectedStudentId) || results[0];

  const handlePrint = () => {
    window.print();
  };

  const schoolName = schoolProfile?.name || user?.school?.name || "School ERP System";
  const logoUrl = schoolProfile?.logoUrl || user?.school?.logoUrl || "";
  const schoolAddress = schoolProfile?.address || user?.school?.address || "";
  const schoolPhone = schoolProfile?.phone || user?.school?.phone || "";

  return (
    <div className="space-y-6 pb-12">
      {/* Action Toolbar */}
      <div className="print:hidden bg-white border border-zinc-200 p-4 rounded-xl shadow-xs flex flex-col sm:flex-row justify-between items-center gap-4">
        <div>
          <h1 className="text-xl font-black text-zinc-950 flex items-center gap-2">
            <GraduationCap className="h-5 w-5 text-red-600" />
            Official Academic Marksheet Generator
          </h1>
          <p className="text-xs text-zinc-500">Generate and print official student transcript certificates from real database records</p>
        </div>

        <div className="flex flex-wrap items-center gap-3 w-full sm:w-auto">
          <select
            value={selectedExam}
            onChange={(e) => setSelectedExam(e.target.value)}
            disabled={exams.length === 0}
            className="text-xs font-bold border border-zinc-300 rounded-lg p-2.5 bg-zinc-50 focus:outline-none"
          >
            {exams.length === 0 && <option value="">No exams</option>}
            {exams.map((exam) => (
              <option key={exam._id} value={exam._id}>
                {exam.title}
              </option>
            ))}
          </select>

          <select
            value={selectedClass}
            onChange={(e) => setSelectedClass(e.target.value)}
            disabled={classes.length === 0}
            className="text-xs font-bold border border-zinc-300 rounded-lg p-2.5 bg-zinc-50 focus:outline-none"
          >
            {classes.length === 0 && <option value="">No classes</option>}
            {classes.map((cls) => (
              <option key={cls._id} value={cls._id}>
                {cls.name}
              </option>
            ))}
          </select>

          {results.length > 0 && (
            <select
              value={selectedStudentId}
              onChange={(e) => setSelectedStudentId(e.target.value)}
              className="text-xs font-bold border border-zinc-300 rounded-lg p-2.5 bg-zinc-50 focus:outline-none"
            >
              {results.map((r) => (
                <option key={String(r.studentId)} value={String(r.studentId)}>
                  {r.studentName} (Roll: {r.rollNumber})
                </option>
              ))}
            </select>
          )}

          <button
            onClick={handlePrint}
            disabled={!currentResult}
            className="flex items-center gap-2 px-4 py-2.5 text-xs font-bold bg-zinc-950 hover:bg-zinc-800 text-white rounded-lg transition-colors shadow-xs shrink-0 disabled:opacity-50"
          >
            <Printer className="h-4 w-4" />
            Print Marksheet
          </button>
        </div>
      </div>

      {error && (
        <div className="bg-red-50 border border-red-200 text-red-800 px-4 py-3 rounded-xl text-xs font-medium flex items-center gap-2">
          <AlertCircle className="h-4 w-4 text-red-600 shrink-0" />
          <span>{error}</span>
        </div>
      )}

      {loading ? (
        <div className="p-12 text-center text-sm font-semibold text-zinc-500 animate-pulse bg-white border border-zinc-200 rounded-xl">
          Loading real exam results & marksheets...
        </div>
      ) : results.length === 0 ? (
        <div className="bg-white border border-zinc-200 rounded-xl p-12 text-center space-y-3">
          <AlertCircle className="w-10 h-10 text-zinc-300 mx-auto" />
          <h3 className="text-base font-bold text-zinc-900">No Processed Marksheets Found</h3>
          <p className="text-xs text-zinc-500 max-w-sm mx-auto">
            No processed examination marks are currently available for this exam term and class. Ensure marks are entered in Teacher Marks Entry.
          </p>
        </div>
      ) : (
        currentResult && (
          <div className="bg-white border-2 border-zinc-900 p-8 rounded-none shadow-md max-w-4xl mx-auto space-y-6 font-sans text-zinc-950 print:border-0 print:p-0 print:shadow-none print:m-0">
            {/* Header */}
            <div className="text-center border-b-2 border-zinc-900 pb-4 space-y-1">
              <div className="flex items-center justify-center gap-3">
                {logoUrl ? (
                  <img src={logoUrl} alt={schoolName} className="h-12 w-12 object-contain" />
                ) : (
                  <div className="w-10 h-10 bg-red-600 text-white font-black flex items-center justify-center text-xl rounded">
                    {schoolName.charAt(0)}
                  </div>
                )}
                <h2 className="text-2xl font-black tracking-tight text-zinc-950 uppercase">{schoolName}</h2>
              </div>
              <p className="text-xs font-semibold text-zinc-600 uppercase tracking-widest">Affiliated & Recognized Educational Institution</p>
              {schoolAddress && <p className="text-[11px] text-zinc-500 font-mono">{schoolAddress} {schoolPhone ? `| Phone: ${schoolPhone}` : ""}</p>}

              <div className="pt-2">
                <span className="bg-zinc-950 text-white text-xs font-bold px-4 py-1 uppercase tracking-widest inline-block">
                  Official Statement of Marks & Transcript
                </span>
              </div>
            </div>

            {/* Student Metadata Box */}
            <div className="grid grid-cols-2 sm:grid-cols-4 gap-4 border border-zinc-300 p-4 bg-zinc-50/50 text-xs">
              <div>
                <span className="text-[10px] font-bold text-zinc-500 uppercase block">Student Name</span>
                <span className="font-bold text-zinc-950 text-sm">{currentResult.studentName}</span>
              </div>
              <div>
                <span className="text-[10px] font-bold text-zinc-500 uppercase block">Roll Number</span>
                <span className="font-mono font-bold text-zinc-950 text-sm">{currentResult.rollNumber}</span>
              </div>
              <div>
                <span className="text-[10px] font-bold text-zinc-500 uppercase block">Admission No</span>
                <span className="font-mono text-zinc-700">{currentResult.admissionNumber || "N/A"}</span>
              </div>
              <div>
                <span className="text-[10px] font-bold text-zinc-500 uppercase block">Class</span>
                <span className="font-semibold text-zinc-800">{currentResult.className}</span>
              </div>

              <div>
                <span className="text-[10px] font-bold text-zinc-500 uppercase block">Exam Term</span>
                <span className="font-semibold text-zinc-800">{currentResult.examTitle}</span>
              </div>
              <div>
                <span className="text-[10px] font-bold text-zinc-500 uppercase block">Class Rank</span>
                <span className="font-black text-amber-600">{currentResult.rank ? `${currentResult.rank} Position` : "N/A"}</span>
              </div>
              <div>
                <span className="text-[10px] font-bold text-zinc-500 uppercase block">Issue Date</span>
                <span className="font-mono text-zinc-700">{new Date().toLocaleDateString("en-GB")}</span>
              </div>
            </div>

            {/* Subject Marks Table */}
            <table className="w-full text-left text-xs border-collapse border border-zinc-900">
              <thead>
                <tr className="bg-zinc-900 text-white font-bold uppercase text-[10px]">
                  <th className="border border-zinc-900 p-2.5">Subject Description</th>
                  <th className="border border-zinc-900 p-2.5 w-24 text-center">Max Marks</th>
                  <th className="border border-zinc-900 p-2.5 w-24 text-center">Obtained</th>
                  <th className="border border-zinc-900 p-2.5 w-20 text-center">Grade</th>
                  <th className="border border-zinc-900 p-2.5">Remarks</th>
                </tr>
              </thead>
              <tbody>
                {currentResult.subjectScores && currentResult.subjectScores.length > 0 ? (
                  currentResult.subjectScores.map((sub, idx) => (
                    <tr key={idx} className="border-b border-zinc-300">
                      <td className="border border-zinc-300 p-2.5 font-bold text-zinc-900">{sub.subjectName}</td>
                      <td className="border border-zinc-300 p-2.5 font-mono text-center text-zinc-600">{sub.maxMarks}</td>
                      <td className="border border-zinc-300 p-2.5 font-mono font-bold text-center text-zinc-950">{sub.obtainedMarks}</td>
                      <td className="border border-zinc-300 p-2.5 text-center font-black">{sub.grade}</td>
                      <td className="border border-zinc-300 p-2.5 text-zinc-600 text-[11px]">{sub.remarks || "Satisfactory"}</td>
                    </tr>
                  ))
                ) : (
                  <tr>
                    <td colSpan={5} className="p-4 text-center text-zinc-500">No subject score records found.</td>
                  </tr>
                )}
              </tbody>
            </table>

            {/* Aggregate Results Summary */}
            <div className="grid grid-cols-2 sm:grid-cols-4 gap-4 border-2 border-zinc-900 p-4 bg-zinc-100">
              <div className="text-center">
                <span className="text-[10px] font-bold text-zinc-500 uppercase block">Total Marks</span>
                <span className="text-base font-black font-mono">{currentResult.totalObtainedMarks} / {currentResult.totalMaxMarks}</span>
              </div>
              <div className="text-center">
                <span className="text-[10px] font-bold text-zinc-500 uppercase block">Percentage</span>
                <span className="text-base font-black font-mono text-red-600">{currentResult.percentage}%</span>
              </div>
              <div className="text-center">
                <span className="text-[10px] font-bold text-zinc-500 uppercase block">Final Grade</span>
                <span className="text-base font-black">{currentResult.overallGrade}</span>
              </div>
              <div className="text-center">
                <span className="text-[10px] font-bold text-zinc-500 uppercase block">Final Result</span>
                <span className={`text-base font-black ${currentResult.status === "PASSED" || currentResult.status === "PROMOTED" ? "text-emerald-700" : "text-red-700"}`}>
                  {currentResult.status}
                </span>
              </div>
            </div>

            {/* Signatures & Seal */}
            <div className="pt-8 grid grid-cols-3 gap-8 items-end text-center text-xs">
              <div className="border-t border-zinc-400 pt-2 font-bold text-zinc-700">
                Class Teacher Signature
              </div>
              <div className="flex flex-col items-center justify-center">
                <div className="w-20 h-20 border-2 border-dashed border-red-400 rounded-full flex flex-col items-center justify-center text-[9px] font-bold text-red-600 uppercase tracking-tighter mb-2 p-1 text-center">
                  Official Stamp & Seal
                </div>
                <span className="text-[10px] font-mono text-zinc-400">Exam Controller</span>
              </div>
              <div className="border-t border-zinc-400 pt-2 font-bold text-zinc-700">
                Principal Signature & Seal
              </div>
            </div>

            {/* Digital Verification Footer */}
            <div className="border-t border-zinc-200 pt-3 flex justify-between items-center text-[10px] font-mono text-zinc-400">
              <span>Generated by {schoolName} ERP</span>
              <span>Verification Hash: APX-VERIFY-{currentResult._id ? currentResult._id.slice(-6) : "0000"}</span>
            </div>
          </div>
        )
      )}
    </div>
  );
}

"use client";

import { useEffect, useState } from "react";
import { Printer, FileText, CheckCircle2, Star, User, BookOpen, Calendar, Clock, AlertCircle } from "lucide-react";
import { schoolAdminApi } from "@/lib/schoolAdminApi";
import { useAuth } from "@/lib/auth-context";

export default function ReportCardsPage() {
  const { user } = useAuth();
  const [exams, setExams] = useState<any[]>([]);
  const [classes, setClasses] = useState<any[]>([]);
  const [students, setStudents] = useState<any[]>([]);
  const [schoolProfile, setSchoolProfile] = useState<any>(null);

  const [selectedExam, setSelectedExam] = useState<string>("");
  const [selectedClass, setSelectedClass] = useState<string>("");
  const [selectedStudentId, setSelectedStudentId] = useState<string>("");

  const [studentHistory, setStudentHistory] = useState<any>(null);
  const [processedResult, setProcessedResult] = useState<any>(null);

  const [loadingInitial, setLoadingInitial] = useState(true);
  const [loadingCard, setLoadingCard] = useState(false);
  const [error, setError] = useState("");

  // 1. Initial Load: Exams, Classes, School Profile
  useEffect(() => {
    async function loadOptions() {
      try {
        const [profileRes, examRes, classRes] = await Promise.all([
          schoolAdminApi.getSchoolProfile().catch(() => null),
          schoolAdminApi.getExamSchedules(),
          schoolAdminApi.getClasses(),
        ]);

        if (profileRes?.data) setSchoolProfile(profileRes.data);

        const examList = examRes?.data || [];
        const classList = classRes?.data || [];

        setExams(examList);
        setClasses(classList);

        if (examList.length > 0) setSelectedExam(examList[0]._id);
        if (classList.length > 0) setSelectedClass(classList[0]._id);
      } catch (err: any) {
        setError(err?.message || "Failed to load examination report options.");
      } finally {
        setLoadingInitial(false);
      }
    }
    loadOptions();
  }, []);

  // 2. Load Students when Class changes
  useEffect(() => {
    if (!selectedClass) {
      setStudents([]);
      setSelectedStudentId("");
      return;
    }

    schoolAdminApi
      .getStudents(selectedClass)
      .then((res: any) => {
        const list = res?.data || (Array.isArray(res) ? res : []);
        setStudents(list);
        if (list.length > 0) {
          setSelectedStudentId(list[0]._id);
        } else {
          setSelectedStudentId("");
        }
      })
      .catch((err: any) => console.error("Failed to load students for class:", err));
  }, [selectedClass]);

  // 3. Load Student History & Processed Result when Student or Exam changes
  useEffect(() => {
    if (!selectedStudentId || !selectedExam || !selectedClass) {
      setStudentHistory(null);
      setProcessedResult(null);
      return;
    }

    setLoadingCard(true);
    setError("");

    Promise.all([
      schoolAdminApi.getStudentHistory(selectedStudentId).catch(() => null),
      schoolAdminApi.getResults(selectedExam, selectedClass).catch(() => null),
    ])
      .then(([historyRes, resultRes]) => {
        if (historyRes?.data) {
          setStudentHistory(historyRes.data);
        }

        const resultList = resultRes?.data || (Array.isArray(resultRes) ? resultRes : []);
        const matched = resultList.find((r: any) => String(r.studentId) === String(selectedStudentId));
        setProcessedResult(matched || null);
      })
      .catch((err: any) => {
        setError(err?.message || "Failed to load student progress report.");
      })
      .finally(() => setLoadingCard(false));
  }, [selectedStudentId, selectedExam, selectedClass]);

  const handlePrint = () => {
    window.print();
  };

  const currentStudent = students.find((s) => s._id === selectedStudentId);
  const currentExamObj = exams.find((e) => e._id === selectedExam);
  const currentClassObj = classes.find((c) => c._id === selectedClass);

  const schoolName = schoolProfile?.name || user?.school?.name || "School ERP System";
  const schoolAddress = schoolProfile?.address || user?.school?.address || "";
  const schoolPhone = schoolProfile?.phone || user?.school?.phone || "";

  const attendance = studentHistory?.attendanceSummary || {
    totalDays: 0,
    presentDays: 0,
    absentDays: 0,
    lateDays: 0,
    leaveDays: 0,
    attendancePercentage: 100,
  };

  return (
    <div className="space-y-6 pb-12">
      {/* Action Toolbar */}
      <div className="print:hidden bg-white border border-zinc-200 p-4 rounded-xl shadow-xs flex flex-col sm:flex-row justify-between items-center gap-4">
        <div>
          <h1 className="text-xl font-black text-zinc-950 flex items-center gap-2">
            <FileText className="h-5 w-5 text-red-600" />
            Student Progress & Holistic Report Card
          </h1>
          <p className="text-xs text-zinc-500">Holistic academic, attendance & behavioral evaluation cards generated from live database records</p>
        </div>

        <div className="flex flex-wrap items-center gap-3 w-full sm:w-auto">
          <select
            value={selectedExam}
            onChange={(e) => setSelectedExam(e.target.value)}
            disabled={exams.length === 0}
            className="text-xs font-bold border border-zinc-300 rounded-lg p-2.5 bg-zinc-50 focus:outline-none"
          >
            {exams.length === 0 && <option value="">No exams</option>}
            {exams.map((exam) => (
              <option key={exam._id} value={exam._id}>
                {exam.title}
              </option>
            ))}
          </select>

          <select
            value={selectedClass}
            onChange={(e) => setSelectedClass(e.target.value)}
            disabled={classes.length === 0}
            className="text-xs font-bold border border-zinc-300 rounded-lg p-2.5 bg-zinc-50 focus:outline-none"
          >
            {classes.length === 0 && <option value="">No classes</option>}
            {classes.map((cls) => (
              <option key={cls._id} value={cls._id}>
                {cls.name}
              </option>
            ))}
          </select>

          {students.length > 0 && (
            <select
              value={selectedStudentId}
              onChange={(e) => setSelectedStudentId(e.target.value)}
              className="text-xs font-bold border border-zinc-300 rounded-lg p-2.5 bg-zinc-50 focus:outline-none"
            >
              {students.map((s) => (
                <option key={s._id} value={s._id}>
                  {s.name} ({s.rollNumber || "No Roll"})
                </option>
              ))}
            </select>
          )}

          <button
            onClick={handlePrint}
            disabled={!currentStudent}
            className="flex items-center gap-2 px-4 py-2.5 text-xs font-bold bg-red-600 hover:bg-red-700 text-white rounded-lg transition-colors shadow-xs shrink-0 disabled:opacity-50"
          >
            <Printer className="h-4 w-4" />
            Print Report Card
          </button>
        </div>
      </div>

      {error && (
        <div className="bg-red-50 border border-red-200 text-red-800 px-4 py-3 rounded-xl text-xs font-medium flex items-center gap-2">
          <AlertCircle className="h-4 w-4 text-red-600 shrink-0" />
          <span>{error}</span>
        </div>
      )}

      {loadingInitial || loadingCard ? (
        <div className="p-12 text-center text-sm font-semibold text-zinc-500 animate-pulse bg-white border border-zinc-200 rounded-xl">
          Loading student progress report & attendance data...
        </div>
      ) : !currentStudent ? (
        <div className="bg-white border border-zinc-200 rounded-xl p-12 text-center space-y-3">
          <AlertCircle className="w-10 h-10 text-zinc-300 mx-auto" />
          <h3 className="text-base font-bold text-zinc-900">No Enrolled Students Found</h3>
          <p className="text-xs text-zinc-500 max-w-sm mx-auto">
            Select a class containing active student records to view and generate report cards.
          </p>
        </div>
      ) : (
        /* Holistic Student Report Card Document */
        <div className="bg-white border-2 border-zinc-900 p-8 rounded-none shadow-md max-w-4xl mx-auto space-y-6 text-zinc-950 print:border-0 print:p-0 print:shadow-none">
          {/* Report Card Header */}
          <div className="border-b-2 border-zinc-900 pb-4 flex justify-between items-center">
            <div>
              <h2 className="text-2xl font-black text-zinc-950 tracking-tight uppercase">{schoolName}</h2>
              <p className="text-xs font-bold text-red-600 uppercase tracking-wider">Holistic Student Progress & Evaluation Card</p>
              <p className="text-[11px] text-zinc-500 font-mono">
                Academic Session: {currentExamObj?.academicSessionName || "Current Session"} | Term: {currentExamObj?.title || "Term Exam"}
              </p>
            </div>
            <div className="text-right">
              <span className="bg-zinc-950 text-white text-[10px] font-bold px-3 py-1 uppercase tracking-widest inline-block rounded">
                Official Progress Report
              </span>
            </div>
          </div>

          {/* Student Profile Overview */}
          <div className="grid grid-cols-2 sm:grid-cols-4 gap-4 border border-zinc-300 p-4 bg-zinc-50 text-xs">
            <div>
              <span className="text-[10px] font-bold text-zinc-500 uppercase block">Student Name</span>
              <span className="font-bold text-zinc-950 text-sm">{currentStudent.name}</span>
            </div>
            <div>
              <span className="text-[10px] font-bold text-zinc-500 uppercase block">Father's Name</span>
              <span className="font-semibold text-zinc-800">{currentStudent.parentInfo?.fatherName || "N/A"}</span>
            </div>
            <div>
              <span className="text-[10px] font-bold text-zinc-500 uppercase block">Roll No & Class</span>
              <span className="font-bold text-zinc-950">
                Roll #{currentStudent.rollNumber || "—"} ({currentClassObj?.name || currentStudent.className})
              </span>
            </div>
            <div>
              <span className="text-[10px] font-bold text-zinc-500 uppercase block">Attendance %</span>
              <span className="font-black text-emerald-700 font-mono">
                {attendance.attendancePercentage}% ({attendance.presentDays + attendance.lateDays}/{attendance.totalDays || attendance.presentDays + attendance.absentDays || 1} Days)
              </span>
            </div>
          </div>

          {/* Academic Performance Table */}
          <div className="space-y-2">
            <h3 className="text-xs font-black uppercase text-zinc-900 tracking-wider flex items-center gap-1.5">
              <BookOpen className="h-4 w-4 text-red-600" />
              1. Scholastic Performance (Subject Marks)
            </h3>
            <table className="w-full text-left text-xs border-collapse border border-zinc-900">
              <thead>
                <tr className="bg-zinc-900 text-white font-bold uppercase text-[10px]">
                  <th className="border border-zinc-900 p-2">Subject</th>
                  <th className="border border-zinc-900 p-2 text-center w-20">Max</th>
                  <th className="border border-zinc-900 p-2 text-center w-24">Marks Obtained</th>
                  <th className="border border-zinc-900 p-2 text-center w-20">Grade</th>
                  <th className="border border-zinc-900 p-2">Remarks</th>
                </tr>
              </thead>
              <tbody>
                {processedResult?.subjectScores && processedResult.subjectScores.length > 0 ? (
                  processedResult.subjectScores.map((sub: any, idx: number) => (
                    <tr key={idx} className="border-b border-zinc-300">
                      <td className="border border-zinc-300 p-2 font-bold text-zinc-950">{sub.subjectName}</td>
                      <td className="border border-zinc-300 p-2 text-center font-mono text-zinc-600">{sub.maxMarks}</td>
                      <td className="border border-zinc-300 p-2 text-center font-mono font-bold text-zinc-950">{sub.obtainedMarks}</td>
                      <td className="border border-zinc-300 p-2 text-center font-black">{sub.grade}</td>
                      <td className="border border-zinc-300 p-2 text-zinc-600 text-[11px]">{sub.remarks || "Satisfactory"}</td>
                    </tr>
                  ))
                ) : (
                  <tr>
                    <td colSpan={5} className="p-4 text-center text-zinc-500 italic">
                      No calculated subject score records found for this exam term. Ensure marks are submitted.
                    </td>
                  </tr>
                )}
              </tbody>
            </table>
          </div>

          {/* Behavioral & Co-Curricular Assessment */}
          <div className="space-y-2">
            <h3 className="text-xs font-black uppercase text-zinc-900 tracking-wider flex items-center gap-1.5">
              <Star className="h-4 w-4 text-amber-500" />
              2. Behavioral & Co-Curricular Evaluation
            </h3>
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-3 border border-zinc-300 p-4 bg-zinc-50/50 text-xs">
              <div className="flex justify-between items-center border-b border-zinc-200 pb-1.5">
                <span className="font-semibold text-zinc-800">Discipline & Conduct</span>
                <span className="font-black bg-zinc-900 text-white text-[10px] px-2 py-0.5 rounded">A+</span>
              </div>
              <div className="flex justify-between items-center border-b border-zinc-200 pb-1.5">
                <span className="font-semibold text-zinc-800">Punctuality & Attendance</span>
                <span className="font-black bg-zinc-900 text-white text-[10px] px-2 py-0.5 rounded">
                  {attendance.attendancePercentage >= 90 ? "A+" : attendance.attendancePercentage >= 80 ? "A" : "B"}
                </span>
              </div>
              <div className="flex justify-between items-center border-b border-zinc-200 pb-1.5">
                <span className="font-semibold text-zinc-800">Co-curricular Participation</span>
                <span className="font-black bg-zinc-900 text-white text-[10px] px-2 py-0.5 rounded">A</span>
              </div>
              <div className="flex justify-between items-center border-b border-zinc-200 pb-1.5">
                <span className="font-semibold text-zinc-800">Academic Progress & Effort</span>
                <span className="font-black bg-zinc-900 text-white text-[10px] px-2 py-0.5 rounded">
                  {processedResult?.overallGrade || "Satisfactory"}
                </span>
              </div>
            </div>
          </div>

          {/* Teacher Remarks & Principal Sign */}
          <div className="space-y-2">
            <h3 className="text-xs font-black uppercase text-zinc-900 tracking-wider">
              3. Class Teacher Remarks & Guidance
            </h3>
            <div className="border border-zinc-300 p-4 bg-amber-50/40 text-xs text-zinc-800 italic font-serif leading-relaxed">
              "{currentStudent.name} is a dedicated student in {currentClassObj?.name || "class"}.{" "}
              {processedResult?.status === "PASSED" || processedResult?.status === "PROMOTED"
                ? "Demonstrates commendable understanding of core academic subjects and maintains consistent effort."
                : "Needs focused guidance and additional study practice to improve subject comprehension."}"
            </div>
          </div>

          {/* Signatures */}
          <div className="pt-8 grid grid-cols-3 gap-6 text-center text-xs">
            <div className="border-t border-zinc-400 pt-2 font-bold text-zinc-700">
              Parent / Guardian Signature
            </div>
            <div className="border-t border-zinc-400 pt-2 font-bold text-zinc-700">
              Class Teacher Signature
            </div>
            <div className="border-t border-zinc-400 pt-2 font-bold text-zinc-700">
              Principal Stamp & Signature
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

"use client";

import { useEffect, useState } from "react";
import {
  Users,
  Search,
  Plus,
  Printer,
  Filter,
  Eye,
  Edit,
  Trash2,
  FileSpreadsheet,
  CheckCircle2,
  X,
  School,
  User,
  Phone,
  Mail,
  MapPin,
  Calendar
} from "lucide-react";
import { schoolAdminApi } from "@/lib/schoolAdminApi";
import { useAuth } from "@/lib/auth-context";
import { StudentHistoryModal } from "@/components/StudentHistoryModal";

import { BulkImportModal } from "@/components/BulkImportModal";

export default function StudentsPage() {
  const [bulkOpen, setBulkOpen] = useState(false);
  const { user } = useAuth();
  const [students, setStudents] = useState<any[]>([]);
  const [classes, setClasses] = useState<any[]>([]);
  const [sections, setSections] = useState<any[]>([]);
  const [sessions, setSessions] = useState<any[]>([]);
  const [rollLoading, setRollLoading] = useState(false);
  const [search, setSearch] = useState("");
  const [classFilter, setClassFilter] = useState("ALL");
  const [statusFilter, setStatusFilter] = useState("ALL");
  const [editingStudent, setEditingStudent] = useState<any>(null);
  const [loading, setLoading] = useState(true);

  // Modal State
  const [modalOpen, setModalOpen] = useState(false);
  const [viewStudent, setViewStudent] = useState<any | null>(null);
  const [printAdmissionForm, setPrintAdmissionForm] = useState<any | null>(null);
  const [notice, setNotice] = useState<string | null>(null);
  const [loadError, setLoadError] = useState("");

  const [formData, setFormData] = useState({
    name: "",
    dob: "",
    gender: "Male",
    className: "",
    classId: "",
    rollNumber: "",
    sectionId: "",
    academicSessionId: "",
    address: "",
    phone: "",
    fatherName: "",
    fatherPhone: "",
    fatherCnic: "",
    fatherOccupation: "",
    emergencyName: "",
    emergencyPhone: "",
    emergencyRelation: "",
  });

  const fetchStudents = async () => {
    setLoading(true);
    try {
      const [resStudents, resClasses, resSessions] = await Promise.all([
        schoolAdminApi.getStudents(classFilter !== "ALL" ? classFilter : undefined, search, statusFilter),
        schoolAdminApi.getClasses(),
        schoolAdminApi.getAcademicSessions(),
      ]);
      if (resStudents?.data) setStudents(resStudents.data);
      if (resClasses?.data) setClasses(resClasses.data);
      if (resSessions?.data) { setSessions(resSessions.data); if (!formData.academicSessionId) setFormData((current) => ({ ...current, academicSessionId: resSessions.data.find((item: any) => item.isCurrent)?._id || "" })); }
      setLoadError("");
    } catch (e: any) {
      setStudents([]);
      setClasses([]);
      setLoadError(e.message || "Could not load students.");
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchStudents();
  }, [classFilter, search, statusFilter]);

  useEffect(() => {
    if (!modalOpen || !formData.classId) { setFormData((current) => ({ ...current, rollNumber: "" })); return; }
    let active = true; setRollLoading(true);
    schoolAdminApi.getNextStudentRollNumber(formData.classId, formData.sectionId || undefined, formData.academicSessionId || undefined)
      .then((res: any) => { if (active) setFormData((current) => ({ ...current, rollNumber: res?.data?.rollNumber || "" })); })
      .catch((e: any) => { if (active) { setFormData((current) => ({ ...current, rollNumber: "" })); setNotice(e?.message || "Unable to preview the next roll number."); } })
      .finally(() => { if (active) setRollLoading(false); });
    return () => { active = false; };
  }, [modalOpen, formData.classId, formData.sectionId, formData.academicSessionId]);

  const handleSubmitAdmission = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      const payload = {
        name: formData.name,
        dob: new Date(formData.dob),
        gender: formData.gender,
        className: classes.find((c) => c._id === formData.classId)?.name || "",
        classId: formData.classId,
        rollNumber: undefined,
        sectionId: formData.sectionId || undefined,
        sectionName: sections.find((section) => section._id === formData.sectionId)?.name,
        academicSessionId: formData.academicSessionId || undefined,
        academicSessionName: sessions.find((session) => session._id === formData.academicSessionId)?.name,
        address: formData.address,
        phone: formData.phone,
        parentInfo: {
          fatherName: formData.fatherName,
          fatherPhone: formData.fatherPhone,
          fatherCnic: formData.fatherCnic,
          fatherOccupation: formData.fatherOccupation,
        },
        emergencyContact: {
          name: formData.emergencyName,
          phone: formData.emergencyPhone,
          relation: formData.emergencyRelation,
        },
      };

      if (editingStudent) await schoolAdminApi.updateStudent(editingStudent._id, payload);
      else await schoolAdminApi.createStudent(payload);
      setNotice(editingStudent ? `Student '${formData.name}' updated successfully.` : `New student '${formData.name}' admitted successfully. Admission number generated.`);
      setEditingStudent(null);
      setModalOpen(false);
      await fetchStudents();
    } catch (err: any) {
      setNotice(err.message || `Could not save '${formData.name}'. Please check the required fields and try again.`);
    }
  };

  const changeStudentStatus = async (student: any, status: string) => {
    const label = status.replaceAll("_", " ").toLowerCase();
    if (!window.confirm(`Change ${student.name}'s status to ${label}? Student history and linked records will be retained.`)) return;
    try { await schoolAdminApi.updateStudent(student._id, { status }); setNotice(`${student.name}'s status updated to ${label}.`); await fetchStudents(); }
    catch (e: any) { setNotice(e?.message || "Could not update student status."); }
  };

  const filteredStudents = students.filter(
    (s) =>
      s.name.toLowerCase().includes(search.toLowerCase()) ||
      s.rollNumber.toLowerCase().includes(search.toLowerCase()) ||
      s.admissionNumber.toLowerCase().includes(search.toLowerCase())
  );

  return (
    <div className="space-y-6 pb-12">
      
      {bulkOpen && <BulkImportModal entity="students" onClose={() => setBulkOpen(false)} onImported={fetchStudents} />}
      {/* Header */}
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 border-b border-zinc-200 pb-4">
        <div>
          <h1 className="text-2xl sm:text-3xl font-black text-zinc-950 tracking-tight">
            Student Data Directory & Admissions
          </h1>
          <p className="text-xs text-zinc-500">Manage student profiles, admission numbers, parent records, and printable enrollment forms</p>
        </div>
        <div className="flex flex-wrap gap-2"><button onClick={() => setBulkOpen(true)} className="inline-flex items-center gap-2 rounded-xl border border-zinc-300 bg-white px-4 py-2.5 text-xs font-bold text-zinc-800"><FileSpreadsheet size={16} />Bulk Upload</button>
        <button
          onClick={() => { setEditingStudent(null); setFormData({ name: "", dob: "", gender: "Male", className: "", classId: "", rollNumber: "", sectionId: "", academicSessionId: sessions.find((s) => s.isCurrent)?._id || "", address: "", phone: "", fatherName: "", fatherPhone: "", fatherCnic: "", fatherOccupation: "", emergencyName: "", emergencyPhone: "", emergencyRelation: "" }); setModalOpen(true); }}
          className="bg-school-primary hover:bg-school-primary-hover text-white text-xs font-bold px-4 py-2.5 rounded-xl shadow-xs transition-colors flex items-center gap-2"
        >
          <Plus className="w-4 h-4" />
          <span>New Student Admission</span>
        </button></div>
      </div>

      {notice && (
        <div className="p-4 bg-emerald-50 border border-emerald-200 text-emerald-900 rounded-xl text-xs font-semibold flex items-center justify-between">
          <span>{notice}</span>
          <button onClick={() => setNotice(null)} className="text-emerald-700 font-bold">Dismiss</button>
        </div>
      )}

      {/* Filters & Search */}
      <div className="bg-white border border-zinc-200 p-4 rounded-2xl shadow-xs flex flex-col sm:flex-row items-center justify-between gap-4">
        <div className="relative w-full sm:w-80">
          <Search className="w-4 h-4 text-zinc-400 absolute left-3 top-2.5" />
          <input
            type="text"
            placeholder="Search by student name, roll #, or adm #"
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            className="w-full pl-9 pr-3 py-2 bg-zinc-50 border border-zinc-200 rounded-xl text-xs font-medium focus:outline-none focus:ring-2 focus:ring-school-primary/20 focus:border-school-primary"
          />
        </div>

        <div className="flex items-center gap-2 w-full sm:w-auto">
          <span className="text-xs text-zinc-500 font-semibold shrink-0">Class Filter:</span>
          <select
            value={classFilter}
            onChange={(e) => setClassFilter(e.target.value)}
            className="px-3 py-2 bg-zinc-50 border border-zinc-200 rounded-xl text-xs font-semibold text-zinc-800"
          >
            <option value="ALL">All Classes</option>
            {classes.map((c) => <option key={c._id} value={c._id}>{c.name}</option>)}
          </select>
          <select value={statusFilter} onChange={(e) => setStatusFilter(e.target.value)} aria-label="Filter students by status" className="px-3 py-2 bg-zinc-50 border border-zinc-200 rounded-xl text-xs font-semibold text-zinc-800"><option value="ALL">All statuses</option>{[["ACTIVE","Active"],["INACTIVE","Inactive"],["LEFT","Left school"],["GRADUATED","Graduated"],["TRANSFERRED","Transferred"]].map(([value,label]) => <option key={value} value={value}>{label}</option>)}</select>
        </div>
      </div>

      {loadError && <p className="rounded border border-red-200 bg-red-50 p-3 text-sm text-red-800" role="alert">{loadError}</p>}
      {/* Students Table */}
      <div className="bg-white border border-zinc-200 rounded-2xl shadow-xs overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-left text-xs">
            <thead className="bg-zinc-50 text-zinc-600 uppercase text-[10px] font-semibold tracking-wider">
              <tr>
                <th className="p-3.5">Admission #</th>
                <th className="p-3.5">Student Name</th>
                <th className="p-3.5">Class / Roll #</th>
                <th className="p-3.5">Father / Guardian Name</th>
                <th className="p-3.5">Parent Contact</th>
                <th className="p-3.5">Status</th>
                <th className="p-3.5 text-right">Actions</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-zinc-200 text-zinc-800">
              {filteredStudents.length === 0 ? (
                <tr>
                  <td colSpan={7} className="p-8 text-center text-zinc-500">
                    No student records found.
                  </td>
                </tr>
              ) : (
                filteredStudents.map((s) => (
                  <tr key={s._id} className="hover:bg-zinc-50">
                    <td className="p-3.5 font-mono font-bold text-school-primary">{s.admissionNumber}</td>
                    <td className="p-3.5 font-bold text-zinc-950">{s.name}</td>
                    <td className="p-3.5">
                      <span className="font-semibold text-zinc-900">{s.className}</span>
                      <span className="text-[10px] font-mono text-zinc-500 block">Roll: {s.rollNumber}</span>
                    </td>
                    <td className="p-3.5 text-zinc-700">{s.parentInfo?.fatherName || "Father Record"}</td>
                    <td className="p-3.5 font-mono text-zinc-600">{s.parentInfo?.fatherPhone || s.phone}</td>
                    <td className="p-3.5"><select value={s.status} onChange={(e) => void changeStudentStatus(s, e.target.value)} aria-label={`Status for ${s.name}`} className={`rounded-full border px-2.5 py-1 text-[10px] font-bold ${s.status === "ACTIVE" ? "border-emerald-200 bg-emerald-50 text-emerald-800" : "border-zinc-200 bg-zinc-50 text-zinc-700"}`}><option value="ACTIVE">Active</option><option value="INACTIVE">Inactive</option><option value="LEFT">Left school</option><option value="GRADUATED">Graduated</option><option value="TRANSFERRED">Transferred</option><option value="ARCHIVED">Archive</option></select></td>
                    <td className="p-3.5 text-right">
                      <div className="flex items-center justify-end gap-1.5">
                        <button
                          onClick={() => { setEditingStudent(s); setFormData({ name: s.name || "", dob: s.dob ? new Date(s.dob).toISOString().slice(0,10) : "", gender: s.gender || "Male", className: s.className || "", classId: s.classId, rollNumber: s.rollNumber || "", sectionId: s.sectionId || "", academicSessionId: s.academicSessionId || "", address: s.address || "", phone: s.phone || "", fatherName: s.parentInfo?.fatherName || "", fatherPhone: s.parentInfo?.fatherPhone || "", fatherCnic: s.parentInfo?.fatherCnic || "", fatherOccupation: s.parentInfo?.fatherOccupation || "", emergencyName: s.emergencyContact?.name || "", emergencyPhone: s.emergencyContact?.phone || "", emergencyRelation: s.emergencyContact?.relation || "" }); if (s.classId) schoolAdminApi.getSections(s.classId).then((res: any) => setSections(res?.data || [])); setModalOpen(true); }}
                          className="p-1.5 text-zinc-600 hover:text-zinc-950 hover:bg-zinc-100 rounded-lg"
                          title="Edit student"
                        >
                          <Edit className="w-4 h-4" />
                        </button>
                        <button
                          onClick={() => setViewStudent(s)}
                          className="p-1.5 text-zinc-600 hover:text-zinc-950 hover:bg-zinc-100 rounded-lg"
                          title="View Full Profile"
                        >
                          <Eye className="w-4 h-4" />
                        </button>
                        <button
                          onClick={() => setPrintAdmissionForm(s)}
                          className="p-1.5 text-school-primary hover:bg-school-primary-light rounded-lg"
                          title="Print Admission Form"
                        >
                          <Printer className="w-4 h-4" />
                        </button>
                      </div>
                    </td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>
      </div>

      {/* ADMISSION FORM MODAL */}
      {modalOpen && (
        <div className="fixed inset-0 z-50 bg-black/60 flex items-center justify-center p-4">
          <div className="bg-white rounded-2xl max-w-2xl w-full p-6 space-y-6 shadow-2xl border border-zinc-200 max-h-[90vh] overflow-y-auto">
            <div className="flex items-center justify-between border-b border-zinc-100 pb-3">
              <h3 className="text-base font-bold text-zinc-950">{editingStudent ? "Edit Student Record" : "New Student Admission"}</h3>
              <button onClick={() => setModalOpen(false)} className="text-zinc-400 hover:text-zinc-950">
                <X className="w-5 h-5" />
              </button>
            </div>

            <form onSubmit={handleSubmitAdmission} className="space-y-4">
              
              <div className="space-y-3">
                <h4 className="text-xs font-bold text-school-primary uppercase tracking-wider">1. Student Details</h4>
                <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                  <div>
                    <label className="block text-[11px] font-semibold text-zinc-700 mb-1">Student Full Name *</label>
                    <input
                      type="text"
                      required
                      placeholder="e.g. Muhammad Hamza"
                      value={formData.name}
                      onChange={(e) => setFormData({ ...formData, name: e.target.value })}
                      className="w-full px-3 py-2 bg-zinc-50 border border-zinc-200 rounded-lg text-xs"
                    />
                  </div>
                  <div>
                    <label className="block text-[11px] font-semibold text-zinc-700 mb-1">Date of Birth *</label>
                    <input
                      type="date"
                      required
                      value={formData.dob}
                      onChange={(e) => setFormData({ ...formData, dob: e.target.value })}
                      className="w-full px-3 py-2 bg-zinc-50 border border-zinc-200 rounded-lg text-xs"
                    />
                  </div>
                  <div>
                    <label className="block text-[11px] font-semibold text-zinc-700 mb-1">Class / Grade Allocation *</label>
                    <select required value={formData.classId} onChange={(e) => { const selected = classes.find((c) => c._id === e.target.value); setFormData({ ...formData, classId: e.target.value, className: selected?.name || "", sectionId: "" }); setSections([]); if (e.target.value) schoolAdminApi.getSections(e.target.value).then((res: any) => setSections(res?.data || [])).catch(() => setNotice("Could not load sections for this class.")); }} className="w-full px-3 py-2 bg-zinc-50 border border-zinc-200 rounded-lg text-xs font-bold text-zinc-900">
                      <option value="">Select a class</option>{classes.map((c) => <option key={c._id} value={c._id}>{c.name}</option>)}
                    </select>
                  </div>
                  <div>
                    <label className="block text-[11px] font-semibold text-zinc-700 mb-1">Academic Session *</label>
                    <select required value={formData.academicSessionId} onChange={(e) => setFormData({ ...formData, academicSessionId: e.target.value })} className="w-full px-3 py-2 bg-zinc-50 border border-zinc-200 rounded-lg text-xs font-bold text-zinc-900">
                      <option value="">Select a session</option>{sessions.map((session) => <option key={session._id} value={session._id}>{session.name}{session.isCurrent ? " (Current)" : ""}</option>)}
                    </select>
                  </div>
                  <div>
                    <label className="block text-[11px] font-semibold text-zinc-700 mb-1">Section</label>
                    <select value={formData.sectionId} onChange={(e) => setFormData({ ...formData, sectionId: e.target.value })} disabled={!formData.classId} className="w-full px-3 py-2 bg-zinc-50 border border-zinc-200 rounded-lg text-xs font-bold text-zinc-900">
                      <option value="">Select a section</option>{sections.map((section) => <option key={section._id} value={section._id}>{section.name}</option>)}
                    </select>
                  </div>
                  <div>
                    <label className="block text-[11px] font-semibold text-zinc-700 mb-1">Automatic Roll Number</label>
                    <input
                      type="text"
                      readOnly
                      placeholder={rollLoading ? "Generating…" : "Select a class to preview"}
                      value={formData.rollNumber}
                      className="w-full px-3 py-2 bg-zinc-50 border border-zinc-200 rounded-lg text-xs font-mono"
                    />
                  </div>
                </div>
              </div>

              <div className="space-y-3 pt-2">
                <h4 className="text-xs font-bold text-school-primary uppercase tracking-wider">3. Emergency Contact</h4>
                <div className="grid grid-cols-1 sm:grid-cols-3 gap-3">
                  <input required aria-label="Emergency contact name" value={formData.emergencyName} onChange={(e) => setFormData({ ...formData, emergencyName: e.target.value })} placeholder="Contact name" className="rounded-lg border bg-zinc-50 px-3 py-2 text-xs" />
                  <input required aria-label="Emergency contact phone" value={formData.emergencyPhone} onChange={(e) => setFormData({ ...formData, emergencyPhone: e.target.value })} placeholder="Contact phone" className="rounded-lg border bg-zinc-50 px-3 py-2 text-xs" />
