const refId = (value: any) => String(value?._id || value || "");
export default function TeacherMarksEntryPage() {
  const [contexts, setContexts] = useState<any[]>([]); const [selectedKey, setSelectedKey] = useState(""); const [values, setValues] = useState<Record<string, string>>({}); const [remarks, setRemarks] = useState<Record<string, string>>({});
  const [loading, setLoading] = useState(true); const [saving, setSaving] = useState(false); const [error, setError] = useState(""); const [notice, setNotice] = useState("");
  useEffect(() => { teacherApi.getMarksContexts().then((response) => { const list = response.data || []; setContexts(list); if (list[0]) setSelectedKey(`${refId(list[0].exam)}:${refId(list[0].class)}:${refId(list[0].subject)}:${refId(list[0].section)}`); }).catch((e: any) => setError(e.message || "Unable to load assigned examinations.")).finally(() => setLoading(false)); }, []);
  const keyOf = (item: any) => `${refId(item.exam)}:${refId(item.class)}:${refId(item.subject)}:${refId(item.section)}`;
  const context = contexts.find((item) => keyOf(item) === selectedKey);
  useEffect(() => { if (!context) return; const nextValues: Record<string, string> = {}; const nextRemarks: Record<string, string> = {}; context.students.forEach((student: any) => { nextValues[student.studentId] = student.obtainedMarks === "" ? "" : String(student.obtainedMarks); nextRemarks[student.studentId] = student.remarks || ""; }); setValues(nextValues); setRemarks(nextRemarks); setNotice(""); }, [selectedKey, contexts]);
  const options = useMemo(() => contexts.map((item) => ({ key: keyOf(item), label: `${item.exam?.title || "Exam"} · ${item.subject?.name || "Subject"} · ${item.class?.name || "Class"} ${item.section?.name || ""}` })), [contexts]);
  async function save() {
    if (!context) return;
    if (context.students.some((student: any) => values[student.studentId] === "" || !Number.isFinite(Number(values[student.studentId])) || Number(values[student.studentId]) < 0 || Number(values[student.studentId]) > context.maxMarks)) { setError(`Enter marks from 0 to ${context.maxMarks} for every student.`); return; }
    setSaving(true); setError(""); setNotice("");
    try { const response = await teacherApi.saveMarks({ examId: refId(context.exam), classId: refId(context.class), subjectId: refId(context.subject), marksRecords: context.students.map((student: any) => ({ studentId: student.studentId, obtainedMarks: Number(values[student.studentId]), remarks: remarks[student.studentId] || undefined })) }); setNotice(response.message || "Marks saved successfully."); const refreshed = await teacherApi.getMarksContexts(); setContexts(refreshed.data || []); }
    catch (e: any) { setError(e.message || "Unable to save marks."); } finally { setSaving(false); }
  }
  return <div className="mx-auto max-w-6xl space-y-6 pb-12"><header className="flex flex-wrap items-end justify-between gap-4 border-b border-zinc-200 pb-5"><div><p className="text-xs font-semibold uppercase tracking-wider text-school-primary">Examinations</p><h1 className="mt-1 text-3xl font-black">Marks Entry</h1><p className="mt-1 text-sm text-zinc-500">Only exams matching your active subject and class assignments appear here.</p></div><button onClick={() => void save()} disabled={saving || !context?.students?.length} className="inline-flex items-center gap-2 rounded-xl bg-school-primary px-4 py-2.5 text-sm font-bold text-white disabled:opacity-50"><Save size={16} />{saving ? "Saving…" : "Submit marks"}</button></header>
    {error && <p role="alert" className="rounded-xl border border-red-200 bg-red-50 p-3 text-sm text-red-800">{error}</p>}{notice && <p role="status" className="rounded-xl border border-emerald-200 bg-emerald-50 p-3 text-sm text-emerald-800">{notice}</p>}
    {loading ? <p role="status" className="rounded-2xl bg-white p-6 text-sm text-zinc-500">Loading assigned exams…</p> : contexts.length ? <><label className="grid max-w-2xl gap-1 text-xs font-semibold">Exam / subject / class<select value={selectedKey} onChange={(e) => setSelectedKey(e.target.value)} className="rounded-lg border bg-white px-3 py-2.5">{options.map((option) => <option key={option.key} value={option.key}>{option.label}</option>)}</select></label><section className="flex flex-wrap gap-3 rounded-2xl border border-zinc-200 bg-white p-4 text-sm"><span><span className="text-zinc-500">Maximum:</span> {context?.maxMarks}</span><span><span className="text-zinc-500">Passing:</span> {context?.passingMarks}</span><span><span className="text-zinc-500">Entry:</span> {context?.entryStatus}</span></section>{context?.students?.length ? <div className="overflow-x-auto rounded-2xl border border-zinc-200 bg-white"><table className="w-full min-w-[650px] text-left text-sm"><thead className="bg-zinc-50 text-xs uppercase text-zinc-500"><tr><th className="p-3">Roll</th><th className="p-3">Student</th><th className="p-3">Marks / {context.maxMarks}</th><th className="p-3">Remarks</th></tr></thead><tbody>{context.students.map((student: any) => <tr key={student.studentId} className="border-t"><td className="p-3 font-mono">{student.rollNumber}</td><td className="p-3 font-semibold">{student.name}</td><td className="p-3"><input type="number" min="0" max={context.maxMarks} step="0.01" required value={values[student.studentId] ?? ""} onChange={(e) => setValues((current) => ({ ...current, [student.studentId]: e.target.value }))} className="w-32 rounded-lg border px-3 py-2" /></td><td className="p-3"><input value={remarks[student.studentId] || ""} onChange={(e) => setRemarks((current) => ({ ...current, [student.studentId]: e.target.value }))} className="w-full rounded-lg border px-3 py-2" /></td></tr>)}</tbody></table></div> : <p className="rounded-2xl border border-dashed bg-white p-8 text-center text-sm text-zinc-500">No active students in this assigned section.</p>}</> : <div className="rounded-2xl border border-dashed border-zinc-300 bg-white p-10 text-center"><h2 className="font-bold">No assigned exams are available</h2><p className="mt-1 text-sm text-zinc-500">School Admin must schedule an exam for one of your assigned subjects and classes.</p></div>}
  </div>;
}

